import React from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { ArrowLeft, ChevronRight, Clock3, MapPin, MessageSquare, Phone, Truck } from 'lucide-react';
import { formatUZS, nextLabel, nextStatus, statusMeta } from '../data/mock';
import { useCourier } from '../lib/store';
import { EmptyState, MapView, StatusBadge, cn } from '../components/ui';

const STEPS = ['new', 'accepted', 'picked_up', 'on_the_way', 'delivered'];

export const OrderDetail = () => {
  const { t } = useTranslation();
  const { id } = useParams();
  const navigate = useNavigate();
  const { orders, updateStatus } = useCourier();
  const order = orders.find((o) => o.id === id);

  if (!order) {
    return (
      <div className="pt-4">
        <button onClick={() => navigate(-1)} className="btn-secondary btn-sm mb-4"><ArrowLeft size={14} /> {t('back')}</button>
        <EmptyState icon={<Truck size={26} />} title={t('noOrders')} description={t('noActiveDesc')} />
      </div>
    );
  }

  const stepIndex = STEPS.indexOf(order.status);
  const next = nextStatus[order.status];
  const active = ['new', 'accepted', 'picked_up', 'on_the_way'].includes(order.status);

  return (
    <div className="stagger space-y-4">
      <div className="flex items-center gap-3">
        <button onClick={() => navigate(-1)} className="icon-btn h-9 w-9 transition"><ArrowLeft size={15} /></button>
        <div>
          <h1 className="font-display text-lg font-extrabold leading-none tracking-tight">#{order.id}</h1>
          <p className="mt-1 text-[10px] font-bold text-[var(--muted)]">{t('orderId')} · {order.createdAt}</p>
        </div>
        <span className="ml-auto"><StatusBadge status={order.status} /></span>
      </div>

      <MapView height="h-52" eta={String(order.eta || '')} compact />

      <div className="card p-4">
        <div className="space-y-3">
          <div className="flex items-start gap-3">
            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-2xl bg-brand-500/10 text-brand-600 dark:text-brand-400"><MapPin size={15} /></span>
            <div>
              <p className="text-[10px] font-bold uppercase tracking-wider text-[var(--muted)]">{t('pickup')}</p>
              <p className="text-[11px] font-extrabold">Toshkent, Absalom ko'chasi 4</p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-2xl bg-rose-500/10 text-rose-600 dark:text-rose-400"><MapPin size={15} /></span>
            <div>
              <p className="text-[10px] font-bold uppercase tracking-wider text-[var(--muted)]">{t('dropoff')}</p>
              <p className="text-[11px] font-extrabold">{order.address}</p>
              <p className="mt-0.5 text-[10px] text-[var(--muted)]">{order.details}</p>
            </div>
          </div>
        </div>
        {order.note && (
          <div className="mt-3 rounded-2xl border border-amber-400/30 bg-amber-400/10 px-3.5 py-2.5">
            <p className="text-[9px] font-extrabold uppercase tracking-wider text-amber-600 dark:text-amber-400">{t('orderNote')}</p>
            <p className="mt-0.5 text-[10px] font-bold">{order.note}</p>
          </div>
        )}
      </div>

      <div className="card p-4">
        <div className="mb-3 flex items-center justify-between">
          <h2 className="font-display text-[15px] font-extrabold tracking-tight">{t('status')}</h2>
          <span className="text-[9px] font-bold text-[var(--muted)]">{order.slot}</span>
        </div>
        <ol>
          {STEPS.map((step, i) => {
            const done = i < stepIndex;
            const current = i === stepIndex;
            return (
              <li key={step} className="flex gap-3">
                <div className="flex flex-col items-center">
                  <span className={cn('flex h-6 w-6 items-center justify-center rounded-full border-2 text-[9px] font-black transition', done && 'border-brand-500 bg-gradient-to-br from-brand-600 to-lime-400 text-white shadow-glow', current && 'border-brand-500 bg-brand-500/15 text-brand-600 dark:text-brand-400', !done && !current && 'border-[var(--border)] bg-[var(--surface-2)] text-[var(--muted)]')}>{done ? '✓' : i + 1}</span>
                  {i < STEPS.length - 1 && <span className={cn('h-5 w-0.5', done ? 'bg-brand-500 shadow-glow' : 'bg-[var(--border)]')} />}
                </div>
                <div className="pb-0.5">
                  <p className={cn('text-[11px] font-extrabold', !done && !current && 'text-[var(--muted)]')}>{t(statusMeta[step].labelKey)}</p>
                  {current && order.status !== 'new' && <p className="mt-0.5 text-[9px] text-[var(--muted)]">{order.eta} {t('min')} · {order.distance} {t('km')}</p>}
                </div>
              </li>
            );
          })}
        </ol>
      </div>

      <div className="card p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="accent-bg flex h-11 w-11 items-center justify-center rounded-2xl text-[11px] font-extrabold text-white shadow-glow">{order.customer.split(' ').map((n) => n[0]).slice(0, 2).join('')}</span>
            <div>
              <p className="text-[11px] font-extrabold">{t('customer')}</p>
              <p className="text-[10px] text-[var(--muted)]">{order.customer}</p>
            </div>
          </div>
          <div className="flex gap-2">
            <a href={`tel:${order.phone.replace(/\s/g, '')}`} className="icon-btn h-9 w-9 transition hover:text-brand-600"><Phone size={15} /></a>
            <button className="icon-btn h-9 w-9 transition hover:text-brand-600"><MessageSquare size={15} /></button>
          </div>
        </div>
      </div>

      <div className="card p-4">
        <h2 className="mb-3 font-display text-[15px] font-extrabold tracking-tight">{t('items')}</h2>
        <div className="space-y-1.5">
          {order.items.map((item) => (
            <div key={item.name} className="card-soft flex items-center justify-between px-3.5 py-2.5">
              <span className="flex items-center gap-2.5 text-[11px] font-bold"><span className="text-base">{item.emoji}</span> {item.name}</span>
              <span className="text-[10px] font-extrabold text-[var(--muted)]">×{item.qty}</span>
            </div>
          ))}
        </div>
        <div className="mt-3.5 space-y-2 border-t pt-3.5">
          <div className="flex items-center justify-between text-[10px] font-bold text-[var(--muted)]"><span>{t('total')}</span><span>{formatUZS(order.total)}</span></div>
          <div className="flex items-center justify-between text-[12px] font-extrabold"><span>{t('payout')}</span><span className="text-gradient">{formatUZS(order.payout)}</span></div>
          <div className="flex items-center justify-between text-[10px] font-bold text-[var(--muted)]"><span className="flex items-center gap-1"><Clock3 size={10} /> {t('distance')}</span><span>{order.distance} {t('km')} · {order.eta} {t('min')}</span></div>
        </div>
      </div>

      {active && next && (
        <button
          onClick={() => updateStatus(order.id, next)}
          className="btn-primary sticky bottom-24 z-30 w-full shadow-soft"
        >
          {t(nextLabel[order.status])} <ChevronRight size={15} />
        </button>
      )}
      {order.status === 'delivered' && (
        <div className="card animate-pop p-4 text-center">
          <p className="text-[12px] font-extrabold text-gradient">{t('orderCompleted')} 🎉</p>
        </div>
      )}
    </div>
  );
};
